<script module lang="ts">
/**
 * A settings row: label and description beside one control (`design/components/settings-row.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/settings-row.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { type Snippet } from 'svelte'

import { SlotOutlet, SlotScope, joinSlot } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/settings-row.module.css'
import type { SettingsRowGroupProps } from './SettingsRowGroup.svelte'

export type SettingsGroupProps = SettingsRowGroupProps

export interface SettingsRowProps {
  /**
   * Exactly one governed control: Switch, Select, Checkbox or Button.
   */
  control: Snippet
  description?: string
  label: string
}
</script>

<script lang="ts">
let { control, description, label: labelOwn }: SettingsRowProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const labelId = $derived(`${uid}-label`)
const descriptionId = $derived(`${uid}-description`)
const controlScope: SlotScope = new SlotScope({
  pass: (): Record<string, unknown> => ({
    'aria-labelledby': labelId,
    'aria-describedby': description === undefined ? undefined : descriptionId,
  }),
})
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div class={styles.row} data-member="settings-row"
    ><div class={styles.text}
      ><span class={styles.label} id={labelId}>{label}</span
      >{#if description !== undefined
        }<span class={styles.description} id={descriptionId}>{description}</span
      >{/if
    }</div
    ><div class={styles.control}><SlotOutlet scope={controlScope} snippet={control} /></div
  ></div
>{/if
}{@render joined.end?.()}
